import pandas as pd

def clean(df):
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    allowed_species = {'Adelie', 'Chinstrap', 'Gentoo'}
    df = df[df['species'].isin(allowed_species)]
    valid_range = (df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)
    df = df[valid_range]
    df = df.dropna(subset=['body_mass_g'])
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].mean().to_dict()
